/**
 * Instanced unit-proxy renderer (SPEC §8 "Units"): one draw call for all sprites of an
 * atlas. Per-instance prev/cur positions are uploaded once per snapshot; the vertex shader
 * interpolates with a uniform `uT`, so per-frame CPU cost is constant regardless of count.
 *
 * Positions are f32 offsets from an integer origin chosen at upload time (camera-relative
 * precision, SPEC §8); the camera offset from that origin is computed in f64 on the CPU.
 */
import * as twgl from 'twgl.js';
import type { Camera } from '../camera';
import { isShipFrame, smallFrameOf } from '../../shared/unitLooks';
import { hash2 } from '../hash';
import { ATLAS_FRAMES } from './atlas';
import { BALL_FS, BALL_VS, HERO_BIT, HERO_SCALE } from './ballShader';

/** The share of a frame's fraction above a half that carries a marching sprite's phase. */
const MARCH_SPAN = 0.49;

/**
 * What a sprite on the march adds to its frame in the instance data: a half and up to
 * MARCH_SPAN more, the more being where it is in its walk or its shake, by `seed` (an element's
 * id, a figure's number in its element). A sprite's own: the same in every snapshot, so the walk
 * goes on over a tick's end, and a turret that copies its hull's frame fraction shakes with it.
 */
export function marchFraction(seed: number): number {
  return 0.5 + MARCH_SPAN * (hash2(seed, 0x6d61) / 2 ** 32);
}

/** Whether each frame of the atlas is a ship's (`isShipFrame`), for the shader: GLSL floats. */
const SHIP_OF = Array.from({ length: ATLAS_FRAMES }, (_, frame) => (isShipFrame(frame) ? '1.0' : '0.0')).join(', ');

const VS = `#version 300 es
precision highp float;
in vec2 aCorner;            // per-vertex quad corner in [-0.5, 0.5]
in vec4 aPrevCur;           // per-instance prev.xy, cur.xy (cells, relative to origin)
in vec4 aMisc;              // facing (rad), size (cells), frame (+ marchFraction on the march), alpha
in vec4 aColor;             // tint (normalised u8)
in float aState;            // the countryballs' state bits; here only a hero's (HERO_BIT, PLAN 7.184b2)
uniform vec2 uCam;          // camera centre relative to origin (cells)
uniform float uScale;       // device px per cell
uniform vec2 uViewport;     // device px
uniform float uT;           // interpolation factor in [0, 1]
uniform float uMinPx;       // minimum sprite size in device px
uniform float uMaxPx;       // maximum sprite size in device px
uniform float uSizeMul;     // unit-size setting (PLAN 1.39a)
uniform float uTime;        // seconds, for the walk/drive animation (PLAN 2.3)
uniform float uAlpha;       // layer opacity (tier fades)
uniform float uSmall;       // the small frames' share, 0–1 (PLAN 3.6e3b)
uniform float uSmallOf[${ATLAS_FRAMES}]; // each frame's small one (smallFrameOf)
uniform float uFrameMinPx[${ATLAS_FRAMES}]; // each frame's least size in device px (a ship's, PLAN 4.12c)
out vec2 vUv;
out vec2 vUvSmall;
out float vSmall;
out vec4 vColor;
out float vShip;
// A ship's frame is in two parts (PLAN 7.41b, splitShipTint): red the hull, tinted; green its marks, grey.
const float SHIP[${ATLAS_FRAMES}] = float[${ATLAS_FRAMES}](${SHIP_OF});
void main() {
  vec2 pos = mix(aPrevCur.xy, aPrevCur.zw, uT);
  float frame = floor(aMisc.z);
  float sizePx = min(max(aMisc.y * uScale, max(uMinPx, uFrameMinPx[int(frame)])), uMaxPx) * uSizeMul;
  // A hero (PLAN 7.184b2): its kind's size, clamped as any, then HERO_SCALE × that.
  if ((int(aState + 0.5) & ${HERO_BIT}) != 0) sizePx *= ${HERO_SCALE.toFixed(1)};
  // Moving (frame + 0.5 and up): infantry sway side to side at a walking cadence, vehicles judder.
  // The rest of the fraction is the sprite's phase (marchFraction): its own from tick to tick,
  // and a turret's is its hull's (PLAN 3.6a).
  float part = aMisc.z - frame;
  float moving = step(0.25, part);
  float phase = 6.2832 * (part - 0.5) / ${MARCH_SPAN.toFixed(2)};
  vec2 local = aCorner;
  if (frame < 0.5) local += moving * vec2(0.0, 0.07 * sin(uTime * 9.0 + phase));
  else local += moving * vec2(0.03 * sin(uTime * 31.0 + phase), 0.0);
  float c = cos(aMisc.x);
  float s = sin(aMisc.x);
  vec2 corner = vec2(c * local.x - s * local.y, s * local.x + c * local.y) * sizePx;
  vec2 px = (pos - uCam) * uScale + corner;
  gl_Position = vec4(px.x / (0.5 * uViewport.x), -px.y / (0.5 * uViewport.y), 0.0, 1.0);
  vUv = vec2((frame + aCorner.x + 0.5) / ${ATLAS_FRAMES.toFixed(1)}, aCorner.y + 0.5);
  // Where sprites are small, a frame goes over into its small one, and one that has none there
  // (a turret) goes out.
  float small = uSmallOf[int(frame)];
  float gone = step(small, -0.5);
  vSmall = uSmall * step(0.5, abs(small - frame)) * (1.0 - gone);
  vUvSmall = vec2((max(small, 0.0) + aCorner.x + 0.5) / ${ATLAS_FRAMES.toFixed(1)}, aCorner.y + 0.5);
  vColor = vec4(aColor.rgb, aColor.a * aMisc.w * uAlpha * (1.0 - gone * uSmall));
  vShip = SHIP[int(frame)];
}
`;

const FS = `#version 300 es
precision highp float;
uniform sampler2D uAtlas;
in vec2 vUv;
in vec2 vUvSmall;
in float vSmall;
in vec4 vColor;
in float vShip;
out vec4 outColor;
void main() {
  vec4 t = texture(uAtlas, vUv);
  if (vSmall > 0.0) t = mix(t, texture(uAtlas, vUvSmall), vSmall);
  // White silhouette → tint; dark outline stays dark. The atlas is premultiplied (PLAN 7.21b), so
  // is what is drawn: the tint's alpha scales the colour as well.
  vec3 c = vShip > 0.5 ? t.r * vColor.rgb + vec3(t.g) : t.rgb * vColor.rgb;
  outColor = vec4(c * vColor.a, t.a * vColor.a);
  if (outColor.a < 0.02) discard;
}
`;

/** `smallFrameOf` of every frame of the atlas, for the shader. */
const SMALL_OF = Array.from({ length: ATLAS_FRAMES }, (_, frame) => smallFrameOf(frame));
/** No least size by frame. */
const NO_FRAME_MIN: readonly number[] = Array.from({ length: ATLAS_FRAMES }, () => 0);

/** No upper limit to a sprite's size (a finite number: the shader takes it as a float). */
const NO_MAX_PX = 1e9;

/** Floats per instance in the position/misc buffer. */
export const PROXY_STRIDE = 8;
const STRIDE = PROXY_STRIDE;
/**
 * The attributes' places, the same in both programs (the classic sprites and the countryballs,
 * PLAN 7.174c), so that one vertex array serves both.
 */
const ATTRIBS = { aCorner: 0, aPrevCur: 1, aMisc: 2, aColor: 3, aFlag: 4, aState: 5 } as const;

export class ProxyRenderer {
  readonly gl: WebGL2RenderingContext;
  private readonly program: twgl.ProgramInfo;
  private readonly vao: WebGLVertexArrayObject;
  private readonly instBuf: WebGLBuffer;
  private readonly colorBuf: WebGLBuffer;
  private readonly flagBuf: WebGLBuffer;
  private readonly stateBuf: WebGLBuffer;
  /** The countryballs' program (PLAN 7.174c), compiled the first time balls are drawn. */
  private ballProgram: twgl.ProgramInfo | null = null;
  private readonly atlas: WebGLTexture;
  private capacity = 0;
  count = 0;
  /** Integer origin (cells) of the uploaded positions. */
  originX = 0;
  originY = 0;
  /** CPU-side instance data: [prevX, prevY, curX, curY, facing, size, frame, alpha]. */
  data = new Float32Array(0);
  colors = new Uint8Array(0);
  /**
   * Each instance's slot in the flag atlas (`flagAtlas.ts`, PLAN 7.174b), for the countryball
   * look; -1 none. Written beside the tint by the element sprites and figures.
   */
  flagSlots = new Float32Array(0);
  /** Each instance's state for the countryballs' faces (`BallState` bits: engaged, hit; PLAN 7.174e). */
  states = new Float32Array(0);

  constructor(gl: WebGL2RenderingContext, atlasCanvas: HTMLCanvasElement) {
    this.gl = gl;
    this.program = twgl.createProgramInfo(gl, [VS, FS], { attribLocations: ATTRIBS });
    // Premultiplied (PLAN 7.21b, ADR-497): the mipmaps are averages of colour by its alpha. Straight,
    // the clear texels' black went into every smaller level, and a sprite of a few px was drawn
    // near black, whatever its nation: at 25 m/px German and Polish men 25 apart in RGB (132 at 10).
    this.atlas = twgl.createTexture(gl, { src: atlasCanvas, min: gl.LINEAR_MIPMAP_LINEAR, mag: gl.LINEAR, wrap: gl.CLAMP_TO_EDGE, premultiplyAlpha: 1 });
    this.vao = gl.createVertexArray()!;
    gl.bindVertexArray(this.vao);
    const corner = gl.createBuffer()!;
    gl.bindBuffer(gl.ARRAY_BUFFER, corner);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-0.5, -0.5, 0.5, -0.5, -0.5, 0.5, 0.5, 0.5]), gl.STATIC_DRAW);
    const loc = (n: keyof typeof ATTRIBS): number => ATTRIBS[n];
    gl.enableVertexAttribArray(loc('aCorner'));
    gl.vertexAttribPointer(loc('aCorner'), 2, gl.FLOAT, false, 0, 0);
    this.instBuf = gl.createBuffer()!;
    gl.bindBuffer(gl.ARRAY_BUFFER, this.instBuf);
    gl.enableVertexAttribArray(loc('aPrevCur'));
    gl.vertexAttribPointer(loc('aPrevCur'), 4, gl.FLOAT, false, STRIDE * 4, 0);
    gl.vertexAttribDivisor(loc('aPrevCur'), 1);
    gl.enableVertexAttribArray(loc('aMisc'));
    gl.vertexAttribPointer(loc('aMisc'), 4, gl.FLOAT, false, STRIDE * 4, 16);
    gl.vertexAttribDivisor(loc('aMisc'), 1);
    this.colorBuf = gl.createBuffer()!;
    gl.bindBuffer(gl.ARRAY_BUFFER, this.colorBuf);
    gl.enableVertexAttribArray(loc('aColor'));
    gl.vertexAttribPointer(loc('aColor'), 4, gl.UNSIGNED_BYTE, true, 0, 0);
    gl.vertexAttribDivisor(loc('aColor'), 1);
    this.flagBuf = gl.createBuffer()!;
    gl.bindBuffer(gl.ARRAY_BUFFER, this.flagBuf);
    gl.enableVertexAttribArray(loc('aFlag'));
    gl.vertexAttribPointer(loc('aFlag'), 1, gl.FLOAT, false, 0, 0);
    gl.vertexAttribDivisor(loc('aFlag'), 1);
    this.stateBuf = gl.createBuffer()!;
    gl.bindBuffer(gl.ARRAY_BUFFER, this.stateBuf);
    gl.enableVertexAttribArray(loc('aState'));
    gl.vertexAttribPointer(loc('aState'), 1, gl.FLOAT, false, 0, 0);
    gl.vertexAttribDivisor(loc('aState'), 1);
    gl.bindVertexArray(null);
  }

  /** Ensures CPU arrays hold `n` instances (contents preserved). */
  reserve(n: number): void {
    if (n <= this.data.length / STRIDE) return;
    const d = new Float32Array(n * STRIDE);
    d.set(this.data);
    this.data = d;
    const c = new Uint8Array(n * 4);
    c.set(this.colors);
    this.colors = c;
    const f = new Float32Array(n).fill(-1);
    f.set(this.flagSlots);
    this.flagSlots = f;
    const st = new Float32Array(n);
    st.set(this.states);
    this.states = st;
  }

  /** Uploads the first `count` instances of `data`/`colors` (call once per snapshot). */
  upload(count: number): void {
    const gl = this.gl;
    this.count = count;
    gl.bindBuffer(gl.ARRAY_BUFFER, this.instBuf);
    if (count > this.capacity) {
      this.capacity = Math.max(count, this.capacity * 2);
      gl.bufferData(gl.ARRAY_BUFFER, this.capacity * STRIDE * 4, gl.DYNAMIC_DRAW);
      gl.bindBuffer(gl.ARRAY_BUFFER, this.colorBuf);
      gl.bufferData(gl.ARRAY_BUFFER, this.capacity * 4, gl.DYNAMIC_DRAW);
      gl.bindBuffer(gl.ARRAY_BUFFER, this.flagBuf);
      gl.bufferData(gl.ARRAY_BUFFER, this.capacity * 4, gl.DYNAMIC_DRAW);
      gl.bindBuffer(gl.ARRAY_BUFFER, this.stateBuf);
      gl.bufferData(gl.ARRAY_BUFFER, this.capacity * 4, gl.DYNAMIC_DRAW);
      gl.bindBuffer(gl.ARRAY_BUFFER, this.instBuf);
    }
    gl.bufferSubData(gl.ARRAY_BUFFER, 0, this.data, 0, count * STRIDE);
    gl.bindBuffer(gl.ARRAY_BUFFER, this.colorBuf);
    gl.bufferSubData(gl.ARRAY_BUFFER, 0, this.colors, 0, count * 4);
    gl.bindBuffer(gl.ARRAY_BUFFER, this.flagBuf);
    gl.bufferSubData(gl.ARRAY_BUFFER, 0, this.flagSlots, 0, count);
    gl.bindBuffer(gl.ARRAY_BUFFER, this.stateBuf);
    gl.bufferSubData(gl.ARRAY_BUFFER, 0, this.states, 0, count);
  }

  /**
   * Uploads the places and the misc of instances `first` to `first + n` again, as `data` has them
   * now (a turret's facing between two snapshots, PLAN 3.6b). They must have been uploaded.
   */
  uploadRange(first: number, n: number): void {
    if (n <= 0 || first + n > this.count) return;
    const gl = this.gl;
    gl.bindBuffer(gl.ARRAY_BUFFER, this.instBuf);
    gl.bufferSubData(gl.ARRAY_BUFFER, first * STRIDE * 4, this.data, first * STRIDE, n * STRIDE);
  }

  /**
   * Draws all instances; `wrapOffsets` are world x-shifts (cells) of extra copies for a looping
   * map (see camera.wrapOffsets, with `SEAM_MARGIN`), so sprites near the seam appear on both
   * sides. A sprite is its size in cells at the zoom, at least `minPx` and at most `maxPx` CSS
   * px (before `sizeMul`).
   * `small`: the share of its small frame in each sprite that has one (`smallFrameOf`), 0–1.
   * `frameMinPx`: a least size in CSS px by frame, besides `minPx` (a ship's, PLAN 4.12c).
   */
  draw(cam: Camera, dpr: number, t: number, minPx = 3, wrapOffsets: readonly number[] = [0], sizeMul = 1, timeS = 0, alpha = 1, maxPx = NO_MAX_PX, small = 0, frameMinPx: readonly number[] = NO_FRAME_MIN): void {
    if (this.count === 0) return;
    const gl = this.gl;
    gl.enable(gl.BLEND);
    // Premultiplied colour over what is there; the canvas itself stays opaque (PLAN 2.11m).
    gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
    gl.useProgram(this.program.program);
    twgl.setUniforms(this.program, {
      uAtlas: this.atlas,
      uScale: cam.scale * dpr,
      uViewport: [gl.drawingBufferWidth, gl.drawingBufferHeight],
      uT: Math.min(1, Math.max(0, t)),
      uMinPx: minPx * dpr,
      uMaxPx: maxPx * dpr,
      uSizeMul: sizeMul,
      uTime: timeS,
      uAlpha: alpha,
      uSmall: small,
      uSmallOf: SMALL_OF,
      uFrameMinPx: frameMinPx.map((v) => v * dpr),
    });
    gl.bindVertexArray(this.vao);
    for (const off of wrapOffsets) {
      // A copy shifted by +off appears where the camera is shifted by −off.
      twgl.setUniforms(this.program, { uCam: [cam.cx - off - this.originX, cam.cy - this.originY] });
      gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, this.count);
    }
    gl.bindVertexArray(null);
    gl.disable(gl.BLEND);
  }

  /**
   * Draws the first `count` instances as countryballs (PLAN 7.174c, `ballShader.ts`): sized as `draw`
   * sizes them, upright, each with its nation's flag from `flags` (the flag atlas's texture,
   * `flagH` texels high) by its slot in `flagSlots`, their faces by `states` at `timeS` of the render
   * clock (PLAN 7.174e). The wakes, written after the elements and their turrets, are left out by `count`.
   */
  drawBalls(cam: Camera, dpr: number, t: number, count: number, flags: WebGLTexture, flagH: number, minPx = 3, wrapOffsets: readonly number[] = [0], sizeMul = 1, alpha = 1, maxPx = NO_MAX_PX, frameMinPx: readonly number[] = NO_FRAME_MIN, timeS = 0): void {
    const n = Math.min(count, this.count);
    if (n <= 0) return;
    const gl = this.gl;
    this.ballProgram ??= twgl.createProgramInfo(gl, [BALL_VS, BALL_FS], { attribLocations: ATTRIBS });
    const program = this.ballProgram;
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
    gl.useProgram(program.program);
    twgl.setUniforms(program, {
      uFlags: flags,
      uFlagH: flagH,
      uDpr: dpr,
      uTime: timeS,
      uMarchSpan: MARCH_SPAN,
      uScale: cam.scale * dpr,
      uViewport: [gl.drawingBufferWidth, gl.drawingBufferHeight],
      uT: Math.min(1, Math.max(0, t)),
      uMinPx: minPx * dpr,
      uMaxPx: maxPx * dpr,
      uSizeMul: sizeMul,
      uAlpha: alpha,
      uFrameMinPx: frameMinPx.map((v) => v * dpr),
    });
    gl.bindVertexArray(this.vao);
    for (const off of wrapOffsets) {
      twgl.setUniforms(program, { uCam: [cam.cx - off - this.originX, cam.cy - this.originY] });
      gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, n);
    }
    gl.bindVertexArray(null);
    gl.disable(gl.BLEND);
  }
}
